/*
M+N
                    where
                    M: ℝ^( m×m )
                    N: ℝ^( m×m ) 
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    MatrixD ret;

    heartlib(
        const Eigen::MatrixXd & M,
        const Eigen::MatrixXd & N)
    {
        const long m = M.cols();
        assert( M.rows() == m );
        assert( N.rows() == m );
        assert( N.cols() == m );
        ret = M + N;
    }
};

